package com.desktodo.app;
import android.app.*;import android.os.*;import org.json.*;import java.time.*;import java.util.*;import java.io.*;import android.graphics.Bitmap;
/** Deterministic scene/card fixtures; no live task, notification or display writes. */
public final class ScreenChecks extends Instrumentation {
 int count;void check(boolean b,String why){count++;if(!b)throw new AssertionError(why);}interface Action{void run()throws Exception;}void reject(Action action,String why)throws Exception{boolean failed=false;try{action.run();}catch(Exception e){failed=true;}check(failed,why);}
 @Override public void onCreate(Bundle b){start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  Instant now=Instant.parse("2026-10-18T04:00:00Z");JSONArray history=new JSONArray();for(int i=0;i<4;i++)history.put(new JSONObject().put("id","fixture-"+i).put("recordType","completed").put("completedAt","2026-10-12T00:00:00Z"));history.put(new JSONObject().put("id","old").put("recordType","completed").put("completedAt","2026-10-11T15:59:59Z"));history.put(new JSONObject().put("id","deleted").put("recordType","deleted").put("completedAt","2026-10-13T00:00:00Z"));history.put(history.getJSONObject(0));check(ScreenData.weekCount(history,now)==4,"week boundaries/deleted excluded/duplicate IDs");check(ScreenData.weekCount(history,Instant.parse("2026-10-18T16:00:00Z"))==0,"Monday resets");JSONArray undone=DeskModel.copy(history);undone.remove(0);undone.remove(undone.length()-1);check(ScreenData.weekCount(undone,now)==3,"undo decreases count");check(ScreenData.plantStage(0,20)==0&&ScreenData.plantStage(4,20)==1&&ScreenData.plantStage(30,20)==5,"deterministic growth stages");
  JSONArray kept=ScreenData.ledger(history,new JSONArray(),new JSONArray(),now);check(ScreenData.weekCount(kept,now)==4,"statistics survive history collapse");JSONArray restoredActive=new JSONArray().put(new JSONObject().put("id","fixture-0"));check(ScreenData.weekCount(ScreenData.ledger(kept,history,restoredActive,now),now)==3,"restored active ID removed from ledger");
  JSONObject cfg=ScreenData.datesConfig(DeskModel.defaults(),"项目交付",LocalDate.of(2026,10,20));check(ScreenData.countdown(cfg,now).contains("2 天"),"natural-day countdown");check(ScreenData.countdown(cfg,Instant.parse("2026-10-19T16:00:00Z")).contains("今天"),"midnight target day");check(ScreenData.countdown(cfg,Instant.parse("2026-10-20T16:00:00Z")).contains("已过 1 天"),"passed date count");check(ScreenData.countdown(DeskModel.defaults(),now).contains("添加"),"no fake date fallback");check(ScreenData.term(now).contains("霜降"),"verified term lookup");check(ScreenData.term(Instant.parse("2027-01-01T00:00:00Z")).equals("时令生活"),"unknown year not guessed");check(!ScreenData.lunar(now).contains("不可用"),"ICU lunar conversion");
  long ms=now.toEpochMilli();JSONObject focused=ScreenData.focus(cfg,"start",ms);check(ScreenData.focusRemaining(focused,ms+60000)==24*60000,"real elapsed time");JSONObject paused=ScreenData.focus(focused,"pause",ms+60000);check(ScreenData.focusRemaining(paused,ms+3600000)==24*60000,"pause stable while wall clock advances");JSONObject resumed=ScreenData.focus(paused,"resume",ms+7200000);check(ScreenData.focusRemaining(resumed,ms+7200000)==24*60000,"resume remaining duration");check(ScreenData.focusRemaining(resumed,ms+9000000)==0,"background elapsed clamps at zero");check(ScreenData.focusState(resumed,ms+9000000).contains("完成"),"finished state");check(ScreenData.focus(ScreenData.focus(cfg,"start",ms),"stop",ms).optLong("focusEnd")==0,"stop cancels session");reject(()->ScreenData.focus(cfg,"pause",ms),"cannot pause idle session");
  check(!FocusAlarm.deliverable(focused,ms,"",true),"early/stale alarm cannot notify");check(FocusAlarm.deliverable(focused,ms+25*60000,"",true),"focus expiry eligible");check(!FocusAlarm.deliverable(paused,ms+25*60000,"",true),"paused session never notifies");check(!FocusAlarm.deliverable(focused,ms+25*60000,focused.optString("focusSession")+"|"+focused.optLong("focusEnd"),true),"focus notification deduped");check(!FocusAlarm.deliverable(focused,ms+25*60000,"",false),"notification permission respected");
  JSONArray tasks=new JSONArray().put(DeskModel.task("整理项目进度",null));JSONObject weather=new JSONObject().put("city","苏州").put("fetched",ms).put("current",new JSONObject().put("temperature_2m",22).put("weather_code",2));check(ScreenData.outdoor(weather,now.plusSeconds(3601)).contains("过期"),"weather staleness");
  for(String scene:new String[]{"work","focus","life"}){JSONObject selected=ScreenData.scene(cfg,scene);check(cfg.optString("layout").equals("overview"),"scene selection doesn't mutate previous settings");DeskRenderer renderer=new DeskRenderer(null,tasks,ScreenData.renderConfig(selected,history,now),weather,new JSONArray(),now);renderer.full(DeskModel.layoutId(selected));byte[] frame=renderer.frame();for(int i=8000;i<10400;i++)check(frame[i]==(byte)255,"fixed red band");try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"scene-preview-"+scene+".png"))){renderer.image.compress(Bitmap.CompressFormat.PNG,100,out);}}
  byte[] base=new byte[48000];Arrays.fill(base,(byte)255);base[20*100+90]=0;base[449*100+95]=0;base[180*100+4]=0;
  for(String layout:new String[]{"focus","agenda","overview"})for(String card:ScreenData.CARD_KEYS){JSONObject conf=ScreenData.renderConfig(cfg,history,now).put("layout",layout).put("cardsVersion",1).put("card1",card).put("card2","status").put("statusNote","请稍后联系");DeskRenderer before=new DeskRenderer(base,tasks,conf,weather,new JSONArray(),now);before.cardsPatch(DeskModel.layoutId(conf));byte[] changed=before.frame();int x=layout.equals("overview")?550:572;for(int i=0;i<48000;i++){int px=i%100*8,y=i/100;boolean allowed=(px+8>x&&px<776&&y>=120&&y<402)||(px+8>242&&px<526&&y<80);check(allowed||base[i]==changed[i],"card patch stays in its region");}check(changed[20*100+90]==0&&changed[449*100+95]==0&&changed[180*100+4]==0,"weather/stocks/tasks preserved");JSONObject empty=DeskModel.copy(conf).put("card1","note").put("note","").put("card2","note");DeskRenderer cleared=new DeskRenderer(changed,tasks,empty,weather,new JSONArray(),now);cleared.cardsPatch(DeskModel.layoutId(empty));byte[] fresh=cleared.frame();for(int y=162;y<248;y++)for(int px=x;px<776;px++)check((fresh[y*100+px/8]&(128>>(px%8)))!=0,"old card content fully removed");}
  JSONObject profile=ScreenData.scene(cfg,"work"),state=new JSONObject().put("layout_id",DeskModel.layoutId(profile)).put("phone_settings",profile);check(ScreenSync.acknowledged(profile,state),"lost visual success reply recognized");check(!ScreenSync.acknowledged(DeskModel.copy(profile).put("statusNote","new"),state),"task equality not visual acknowledgement");check(!ScreenSync.patchAllowed("mac.overview.red-v2",profile),"Mac-owned information remains intact");check(!ScreenSync.patchAllowed(DeskModel.layoutId(profile),DeskModel.copy(profile).put("cardsVersion",0)),"legacy baseline not silently migrated");JSONObject different=ScreenData.scene(profile,"life");check(ScreenSync.same(ScreenSync.actual(different,state,false),profile),"failed scene application doesn't replace old card configuration");check(!ScreenSync.sameProfile(state,new JSONObject().put("phone_settings",different)),"concurrent config change detected");check(ScreenData.adopt(DeskModel.defaults(),state).optString("card1").equals("plant"),"read device screen settings without importing histories");reject(()->ScreenData.adopt(profile,new JSONObject().put("layout_id",DeskModel.layoutId(profile)).put("phone_settings",DeskModel.copy(profile).put("weeklyGoal",0))),"invalid device config rejected");
  result.putString("stream","PASS: "+count+" scene/card assertions: week/undo/growth, date/lunar, focus pause/resume, scene render, red band, card cleanup/preservation and profile conflict guards\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL: "+e+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
